(5000076, 729283, 57378, '<td valign="top">Nice image - Like the lighting and the sharpness - Maybe would have cropped a bit off the top of the frame to add some drama and keep us focused on the woman.</td>', 'Nice image - Like the lighting and the sharpness - Maybe would have cropped a bit off the top of the frame to add some drama and keep us focused on the woman.', '2008-10-08 16:32:15.000000', NULL, 1),
