(5005224, 729075, 64518, '<td valign="top">Nice execution with the white on white.</td>', 'Nice execution with the white on white.', '2008-10-12 17:13:20.000000', NULL, 1),
(5005229, 729328, 64518, '<td valign="top">Would have scored higher for me if I could really see what she was doing.  It''s either a sewing machine or something like a band saw (which kinda fits with what looks like a saw in the foreground.)</td>', 'Would have scored higher for me if I could really see what she was doing.  It''s either a sewing machine or something like a band saw (which kinda fits with what looks like a saw in the foreground.)', '2008-10-12 17:14:59.000000', NULL, 1),
