(5007960, 729252, 96721, '<td valign="top">Very nice shot, lovely bokeh and looks really sharp where it needs to be!</td>', 'Very nice shot, lovely bokeh and looks really sharp where it needs to be!', '2008-10-14 13:25:22.000000', NULL, 1),
(5007961, 729341, 96721, '<td valign="top">Hmm not sure if this is just a desat but if so I think it would have worked better as a pure B&amp;W conversion which would have increased the contrast a bit more. Extremely busy background but even so I like the feel of the shot.</td>', 'Hmm not sure if this is just a desat but if so I think it would have worked better as a pure B&W conversion which would have increased the contrast a bit more. Extremely busy background but even so I like the feel of the shot.', '2008-10-14 13:25:45.000000', NULL, 1),
(5007963, 729262, 96721, '<td valign="top">I think this would have worked so much better had there been a greater DOF, those hands would have made a very interesting subject on their own and the bottom right quarter of this shot could have made for a shot with really high impact I think.</td>', 'I think this would have worked so much better had there been a greater DOF, those hands would have made a very interesting subject on their own and the bottom right quarter of this shot could have made for a shot with really high impact I think.', '2008-10-14 13:25:50.000000', NULL, 1),
